var FR_CL=['{x}「Q」','「Q」――{x}の声が、裏返った。','{x}は「Q」とこぼして、背中を反らせた。','{x}の唇から「Q」と甘い声が漏れた。','「Q」{x}はしがみつく腕に力を込めた。','{x}は涙のにじんだ目で「Q」と喘いだ。'];
var FR_ED=['{x}「Q」','{x}は息を乱しながら「Q」と言った。','「Q」と言う{x}の声は、もう震えていた。'];
var FR_AF=['{x}「Q」','{x}は息を整えながら「Q」と言った。','しばらくして、{x}がぽつりと「Q」と言った。'];
function frame(pickFn,frames,list,x){return pickFn(frames).replace('{x}','{'+x+'}').replace('Q',pickFn(list));}
V.line=function(pickFn,persona,kind,x){
var T=kind==='edge'?V.EDGE:kind==='after'?V.AFTER:V.CLIMAX;
var list=T[persona]||T.gentle;
if(!list|| !list.length)return'';
var F=kind==='edge'?FR_ED:kind==='after'?FR_AF:FR_CL;
return frame(pickFn,F,list,x||'b');
};
V.count=function(){
var n=0;
[V.CLIMAX,V.EDGE,V.AFTER].forEach(function(T){Object.keys(T).forEach(function(k){n+=T[k].length;});});
return n;
};
