if(HK.COMMON)HK.COMMON.push({
id:'tie_senpai',cat:'bond',scope:'pair',
when:function(ctx,a,b){return!!(HK.Ties&&HK.Ties.has(ctx,a,b,'senpai'));},
w:function(){return 1;},
run:function(ctx,a,b){
var t=HK.Ties.has(ctx,a,b,'senpai'),S=ctx.chars[t.a],K=ctx.chars[t.b];
var rs=ctx.R(S,K),rk=ctx.R(K,S),k;
if(rk.att>40&&rs.att>25&&HK.canLove&&HK.canLove(K,S)&&ctx.rng()<0.45)k='love';
else if((rs.ten>20||rk.ten>20||K.tr.cp>0.6)&&ctx.rng()<0.4)k='clash';
else k=ctx.rng()<0.5?'a':'b';
if(k==='love')ctx.mod2(S,K,{att:6,aff:4},{att:7,aff:4});
else if(k==='clash')ctx.mod2(S,K,{ten:5,trust:2},{ten:4,trust:3});
else if(k==='a')ctx.mod2(S,K,{aff:3},{trust:5,aff:4});
else ctx.mod2(S,K,{trust:4,aff:3},{aff:3,att:2});
return{cat:k==='love'?'romance':k==='clash'?'conflict':'bond',text:ctx.t(ctx.pick(SENPAI[k]),S,K),why:S.name+'（先輩）と'+K.name+'（後輩）'+{a:'：先輩の面倒見',b:'：後輩の憧れ',clash:'：後輩の成長と張り合い',love:'：憧れが恋に変わる'}[k]};
}
});
var BUDDY=L('{a}と{b}は目配せ一つで左右に分かれた。打ち合わせは要らなかった。|{a}は{b}の背後に回った気配に、振り返りもしなかった。そこにいるのが{b}だと分かっていた。|{a}「私が前、{b}は後ろ」{b}「いつも通りだな」|{a}は{b}の無茶を止めずに、その無茶が成功するよう黙って段取りを整えた。|{a}と{b}は、危ない場面のあとで拳を軽くぶつけ合った。|{a}は{b}の分の水を、言われる前に差し出した。{b}も同じことをしようとしていた。|{a}「{b}が隣にいると、私、失敗する気がしない」{b}「それは過信」|{a}と{b}は言い合いをしながらも、手だけは同じ目的に向かって動いていた。');
