if(typeof v==='string'){if(S.has(v))e[k]=S.fill(v,ac[0],ac[1],ac[2],env);}
else if(Array.isArray(v))v.forEach(function(s,j){if(S.has(s))v[j]=S.fill(s,ac[0],ac[1],ac[2],env);});
