var DG=HK.DG=HK.DG||{};
DG.pool=DG.pool||[];
DG.PARTS={mouth:'唇',ear:'耳',neck:'首筋',chest:'胸',back:'背中',side:'脇腹',belly:'下腹',hips:'腰',thigh:'内腿',feet:'足裏',all:'全身'};
