var dets={};
cases.forEach(function(c){if(c.solved&&c.det!=null)dets[c.det]=(dets[c.det]||0)+1;});
var top=Object.keys(dets).sort(function(a,b){return dets[b]-dets[a];})[0];
if(top!=null)lines.push('探偵役：'+X.nm(+top)+'（'+dets[top]+'件の決め手）');
