function ev(o){
var e={
id:o.id,cat:o.cat,scope:o.scope||'pair',noOdd:true,
when:function(ctx,a,b){
var f=ctx.ft;if(!f)return false;
if(o.tm&&o.tm.indexOf(TC.charAt(f.t))<0)return false;
if(e.scope==='pair'&&(!b|| !together(ctx,a,b)))return false;
if(o.need&& !o.need(ctx,a,b))return false;
return has(ctx,o.pool(ctx,a,b));
},
w:function(ctx,a,b){return typeof o.w==='function'?o.w(ctx,a,b):o.w;},
run:function(ctx,a,b){
var c=o.third?o.third(ctx,a,b):null;
if(o.third&& !c)return null;
var t=o.persona?freshP(ctx,o.pool(ctx,a,b,true),a):fresh(ctx,o.pool(ctx,a,b));
if(!t)return null;
var ex=o.ex?o.ex(ctx,a,b):null;
if(o.fx)o.fx(ctx,a,b,c);
var sp=o.spot?o.spot(ctx,a,b):spotHere(ctx,a,b);
var r={text:fill(ctx,t,a,b,c,ex),why:W(ctx,sp)+(typeof o.why==='function'?o.why(ctx,a,b,c):o.why)};
if(o.food&&HK.Food&&HK.Food.any([a,b])){var fm=HK.Food.daily(ctx,o.food,a,b,null);if(fm){r.text+=fm.text;r.why+='／'+fm.why;}}
if(c)r.with=[c];
if(o.cat2)r.cat=o.cat2(ctx,a,b,c);
return r;
}
};
if(o.persona){var pp=o.pool;o.pool=function(ctx,a,b,raw){var P=pp(ctx,a,b);return raw?P:P[att(a)].concat(P[NEAR[att(a)][0]]);};}
EV.push(e);
return e;
}
