if(!os.length&&P.noneIn([a,b]))os=openNone([a,b],function(){return P.orients(a,b);});
if(!os.length)return P.hardTop(b,a)&& !P.hardTop(a,b)?[b,a]:P.hardTop(a,b)?[a,b]:fb;
