if(!L.length|| !P.forceOn(x))return'';
return'／'+(bare?'':P.FORCE_MARK)+'恋愛対象「なし」の'+L.map(function(c){return c.name;}).join('・')+'も、切羽詰まった場面で体の関係になった（恋愛にはならない）';
