(res.log||[]).forEach(function(e){if(e&&typeof e.text==='string'){var t0=e.text;e.text=NG.fixText(ctx,e.text,cs,Ns);if(NG.debug&&t0!==e.text)NG.debug.push({before:t0,after:e.text});}});
