function wrapJashin(){
var JS=HK.JASHIN;
if(!JS|| !JS.REL|| !JS.REL.substitute||JS.REL.substitute._same)return;
var sub0=JS.REL.substitute;
JS.REL.substitute=function(S,vic){
var r=sub0.apply(this,arguments);
if(!S|| !S.ssPairs|| !vic||r!==vic)return r;
var q=partner(S,vic);
if(!q||q.alive===false||q.out||q.taken||q.bound||q.gone||S.ssUsed[pkey(q,vic)+':subst'])return r;
if(S.rng()<0.3+(q.tr?q.tr.warmth*0.3+q.tr.np*0.15:0.2)){
S.ssUsed[pkey(q,vic)+':see']=1;
var o=emit(S,SS.BOX.jashin,'subst',q,vic);
if(o)ST.key(S,o,q.name+'が同一人物の'+vic.name+'の身代わりに');
if(vic.taken){vic.out=true;vic.esc=S.h;vic.fate='同一人物の'+q.name+'が身代わりになり、逃げ延びた';}
vic.taken=false;
return q;
}
if(!S.ssUsed[pkey(q,vic)+':see']){S.ssUsed[pkey(q,vic)+':subst']=1;emit(S,SS.BOX.jashin,'see',q,vic);}
return r;
};
JS.REL.substitute._same=true;
if(JS.REL.spare&& !JS.REL.spare._same){
var spare0=JS.REL.spare;
JS.REL.spare=function(S,m,v){return spare0.apply(this,arguments)||SS.nk(S,m,v);};
JS.REL.spare._same=true;
}
}
wrapJashin();
