var lastAt=0,errMsg='',fInfo=null,busy=Promise.resolve();
var sig={s:{},h:{}},lastState=null;
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function pad(n){return('0'+n).slice(-2);}
